WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT s.id, s.account_id, s.txn_type, s.txn_time, s.merchant, s.is_flagged, CASE WHEN merchant RLIKE '^(Lazada|Starbucks)$' THEN 'GROUP_A' WHEN merchant RLIKE '^(Grab|7-Eleven)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS merchant_zone, (SELECT SUM(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS sum_transaction_amount FROM islands s;
